// Empareja tus productos con Lococo.
// SYNC_MODE=model -> compara tu "model" con el código de Lococo | SYNC_MODE=sku -> compara tu "sku"
const scraped = $('Scrapear competencia').first().json;
const comp = scraped.items || [];
let mine = $('Mis productos').all().map(i => i.json);
if (mine.length === 1 && Array.isArray(mine[0].products)) mine = mine[0].products;
if (mine.length === 1 && Array.isArray(mine[0].data)) mine = mine[0].data;

const MODE = String($env.SYNC_MODE || 'model').toLowerCase();
const key = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const norm = s => String(s || '').toLowerCase().normalize('NFD')
  .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const tokens = s => new Set(norm(s).split(' ').filter(t => t.length > 1));
const compKey = comp.map(c => key(c.code || c.name));
const compTok = comp.map(c => tokens(c.name));

const out = [];
for (const p of mine) {
  const myKey = key(MODE === 'sku' ? p.sku : p.model);
  const base = {
    mode: MODE, id: p.id ?? null, sku: p.sku ?? null, model: p.model ?? null, name: p.name,
    current_price: Number(p.price), current_description: p.description ?? null,
    usd_rate: scraped.usd_rate || null,
  };

  // 1) Coincidencia exacta del código
  if (myKey) {
    const exact = comp.filter((c, i) => compKey[i] === myKey);
    if (exact.length === 1) {
      out.push({ json: { ...base, exact: true, candidates: exact, match_index: 0, confidence: 1, match_type: 'exacto' } });
      continue;
    }
    // 2) Un código contiene al otro (ej. HAC-B1A21P dentro de DH-HAC-B1A21P-U-0280B)
    if (myKey.length >= 6) {
      const pref = comp.filter((c, i) => compKey[i].includes(myKey) || myKey.includes(compKey[i]));
      if (pref.length === 1) {
        out.push({ json: { ...base, exact: true, candidates: pref, match_index: 0, confidence: 0.9, match_type: 'contiene' } });
        continue;
      }
      if (pref.length > 1) {
        const list = pref.slice(0, 8).map((c, i) => `${i}. ${c.name} — ${c.currency || ''} ${c.price}`).join('\n');
        out.push({ json: { ...base, exact: false, candidates: pref.slice(0, 8), match_type: 'ia',
          prompt: `Mi producto: ${p.name} (modelo ${p.model || '-'})\n\nCandidatos:\n${list}` } });
        continue;
      }
    }
  }

  // 3) Sin código que coincida: candidatos por nombre y decide la IA
  const t = tokens(`${p.model || ''} ${p.name}`);
  const top = comp.map((c, idx) => {
    let inter = 0;
    for (const w of t) if (compTok[idx].has(w)) inter++;
    const union = t.size + compTok[idx].size - inter;
    return { c, score: union ? inter / union : 0 };
  }).filter(x => x.score > 0).sort((a, b) => b.score - a.score).slice(0, 8);
  if (!top.length) continue;
  const candidates = top.map(x => x.c);
  const list = candidates.map((c, i) => `${i}. ${c.name} — ${c.currency || ''} ${c.price}`).join('\n');
  out.push({ json: { ...base, exact: false, candidates, match_type: 'ia',
    prompt: `Mi producto: ${p.name} (modelo ${p.model || '-'})\n\nCandidatos:\n${list}` } });
}
return out;

// Junta la respuesta de la IA con los datos del producto
const p = $('Preparar candidatos').item.json;
let ans = {};
// Formato OpenAI (Groq, Gemini, Ollama /v1) o formato nativo de Ollama
const content = $json.choices?.[0]?.message?.content ?? $json.message?.content ?? '{}';
try { ans = JSON.parse(content); } catch (e) {}
return { json: {
  ...p,
  match_index: Number.isInteger(ans.match_index) ? ans.match_index : -1,
  confidence: Number(ans.confidence) || 0,
} };

// Decide qué actualizar. Todo configurable desde el .env
const num = (v, d) => { const n = parseFloat(v); return Number.isFinite(n) ? n : d; };
const bool = (v, d) => (v === undefined || v === '' ? d : String(v).toLowerCase() === 'true');
const MARGIN = num($env.PRICE_MARGIN_PCT, 0);
const ROUND = Math.max(0.01, num($env.PRICE_ROUND_TO, 1));
const MAX_CHANGE = num($env.MAX_CHANGE_PCT, 30);
const MIN_CONF = num($env.MIN_CONFIDENCE, 0.8);
const IVA = num($env.ADD_IVA_PCT, 0);
const UPD_SKU = bool($env.UPDATE_SKU, true);
const UPD_DESC = bool($env.UPDATE_DESCRIPTION, true);
const TARGET = String($env.TARGET_CURRENCY || 'USD').toUpperCase();
const round2 = n => Math.round(n * 100) / 100;

return $input.all().map((item, i) => {
  const p = item.json;
  const base = { id: p.id, sku: p.sku, model: p.model, name: p.name, mode: p.mode,
    match_type: p.match_type, confidence: p.confidence, current_price: p.current_price };
  const idx = p.match_index;
  if (!Number.isInteger(idx) || idx < 0 || idx >= (p.candidates || []).length)
    return { json: { ...base, action: 'skip', reason: 'sin coincidencia' }, pairedItem: i };
  const m = p.candidates[idx];
  const r = { ...base, source_code: m.code, source_name: m.name, source_price: m.price, source_currency: m.currency };
  if (p.confidence < MIN_CONF)
    return { json: { ...r, action: 'skip', reason: `confianza baja (${p.confidence})` }, pairedItem: i };

  // Precio en la moneda de tu base (TARGET_CURRENCY). Projaska guarda el COSTO en USD.
  const rate = num($env.USD_RATE, p.usd_rate);
  let cost = m.price;
  const srcCur = m.currency || 'ARS';
  if (srcCur !== TARGET) {
    if (!rate) return { json: { ...r, action: 'skip', reason: 'falta cotización para convertir' }, pairedItem: i };
    cost = srcCur === 'USD' ? cost * rate : cost / rate;
    r.usd_rate = rate;
  }
  cost *= (1 + IVA / 100) * (1 + MARGIN / 100);
  const newPrice = TARGET === 'USD' && ROUND <= 1 ? round2(cost) : Math.round(cost / ROUND) * ROUND;
  p.current_price = round2(p.current_price);

  const change = p.current_price ? Math.abs(newPrice - p.current_price) / p.current_price * 100 : 0;
  r.change_pct = Math.round(change * 10) / 10;
  if (p.current_price && change > MAX_CHANGE)
    return { json: { ...r, new_price: newPrice, action: 'review', reason: `cambio de ${r.change_pct}% supera MAX_CHANGE_PCT` }, pairedItem: i };

  // Qué campos cambian
  const set = {};
  if (newPrice !== p.current_price) set.price = newPrice;
  if (p.mode === 'model' && UPD_SKU && m.code && m.code !== p.sku) set.sku = m.code;
  const desc = String(m.name || '').replace(/^.*? — /, '').trim();
  if (UPD_DESC && desc && desc !== p.current_description) set.description = desc;

  if (!Object.keys(set).length) return { json: { ...r, action: 'skip', reason: 'sin cambios' }, pairedItem: i };

  // A quién actualizar: por id si la API lo da; si no, por modelo o sku según el modo
  const match = p.id != null ? { id: p.id } : (p.mode === 'sku' ? { sku: p.sku } : { model: p.model });
  return { json: { ...r, action: 'update', match, set }, pairedItem: i };
});

// Con DRY_RUN distinto de "false" no se toca nada: mirá la salida de "Calcular cambios"
if (String($env.DRY_RUN).toLowerCase() !== 'false') return [];
return $input.all().filter(i => i.json.action === 'update');

// 200 = ok | 404 y 409 = avisos para revisar a mano (no cortan el flujo)
const reqs = $('Solo actualizaciones').all();
const rows = $input.all().map((it, i) => {
  const q = reqs[i]?.json || {};
  const sc = it.json.statusCode;
  const label = { 200: 'ok', 404: 'no encontrado', 409: 'conflicto', 400: 'body inválido', 401: 'token inválido' }[sc] || 'error';
  return { name: q.name, match: q.match, set: q.set, status: sc, result: label,
           detail: it.json.body?.changed ?? it.json.body?.error ?? null };
});
return [{ json: {
  total: rows.length,
  ok: rows.filter(r => r.status === 200).length,
  avisos: rows.filter(r => r.status !== 200),
  cambios: rows.filter(r => r.status === 200 && r.detail && Object.keys(r.detail).length),
} }];
